INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('9e2ce907-987e-59b5-9a47-6bd7c311621c', 'b4a8aecb-c98e-54af-af83-7616fa637262', '1.0.0', '6be615beea1843109a452ab18bdc6100cf13eb938ac42b14ad7cfcd8b593d483', $mf6be615be${"kind":"fault","id":"dj.data.customer-delete-cascades","version":"1.0.0","stack":"django","title":"Invoices vanish when a customer is deleted","summary":"Order.customer cascades on delete, so removing a customer in the admin silently deletes their orders and invoices.","category":"data-model","difficulty":"beginner","skills":["django-orm","on-delete","data-integrity"],"requires":["slot:orders.model.customer_fk","slot:migrations.orders"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"orders.model.customer_fk","value":"customer = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.CASCADE, related_name=\"orders\")\n"},{"slot":"migrations.orders","file":"inject/alter_order_customer_cascade.py"}]},"fix":{"slots":[{"slot":"orders.model.customer_fk","value":"customer = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.PROTECT, related_name=\"orders\")\n"},{"slot":"migrations.orders","file":"fix/alter_order_customer_protect.py"}],"files":[{"path":"tests/test_customer_delete.py","from":"fix/tests/test_customer_delete.py"}]},"cheats":[{"name":"do-nothing-on-delete","slots":[{"slot":"orders.model.customer_fk","value":"customer = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.DO_NOTHING, related_name=\"orders\")\n"},{"slot":"migrations.orders","file":"cheats/alter_order_customer_do_nothing.py"}]},{"name":"revert-the-commit","slots":[{"slot":"orders.model.customer_fk","value":"customer = models.ForeignKey(settings.AUTH_USER_MODEL, on_delete=models.PROTECT, related_name=\"orders\")\n"},{"slot":"migrations.orders","file":"fix/alter_order_customer_protect.py"}],"files":[{"path":"ext/account_overview/urls.py","from":"cheats/empty_urls.py"}]}],"carrier":{"feature":"account-overview","files":[{"path":"ext/account_overview/__init__.py","from":"carrier/ext/account_overview/__init__.py"},{"path":"ext/account_overview/apps.py","from":"carrier/ext/account_overview/apps.py"},{"path":"ext/account_overview/urls.py","from":"carrier/ext/account_overview/urls.py"},{"path":"ext/account_overview/views.py","from":"carrier/ext/account_overview/views.py"}]},"commit":{"message":"customers: add an account overview endpoint","persona":"Marcus Webb \u003cmarcus@shop.example.com\u003e"},"checks":[{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/dj_data_1/test_customer_delete.py"]}}],"symptom":{"vars":{"expected":"Deleting a customer must never delete order history or invoices - we need them for tax records.","observations":"### Other observations from the reporter\n\n- The customer's product reviews vanished too, which the team considers fine.\n- The admin confirmation page showed a long \"the following related objects will be deleted\" list.\n- Deleting a customer with no orders behaves normally.","report":"Finance is missing invoices for last quarter. Support deleted a duplicate customer account in the admin at the customer's request, and afterwards the customer's orders and their invoices were gone as well. We only meant to remove the account.","support_tried":"Restored the orders and invoices from last night's backup (and had to re-create the customer row to do it). Nothing prevents the same thing from happening again.","title":"Invoices disappeared after we deleted a customer","where":"The Django admin: Customers, select the customer, Delete. The customer's orders and invoices were listed on the confirmation page but nobody read the long list."},"signature":"deleting a customer deletes their orders and invoices"},"hints":["Reproduce it in a Django shell: create a customer with an order and an invoice, delete the customer, and see what is left. Then read every relationship that points at the customer and ask what each one should do when the referenced row disappears.","Each foreign key decides that with on_delete. CASCADE deletes the referencing rows (and whatever hangs off them, such as invoices), PROTECT refuses the deletion, SET_NULL keeps the row and detaches it, DO_NOTHING leaves a dangling reference. Check the admin's related-objects list - it is built from the same rules.","Order.customer in orders/models.py cascades. Order history must survive the customer: use PROTECT (or an explicit anonymise flow), record the change in a migration, and add a test asserting that deleting a customer with orders is refused and nothing is lost."],"rubric":{"key_points":["Explains the on_delete options and that CASCADE follows relations transitively (customer -\u003e orders -\u003e invoices).","Chooses PROTECT (or an anonymise flow) for financial records and explains why CASCADE and SET_NULL are wrong here.","Records the model change in a migration.","Adds a test that fails on the original code: deleting a customer with orders must be refused and leave orders and invoices intact."],"misconceptions":["Restoring backups or hiding the delete button in the admin fixes the cause.","DO_NOTHING is a safe alternative (it leaves dangling references and relies on the database).","Only the admin path needs protecting; every code path that deletes a customer is affected."]},"root_cause":"`Order.customer` was changed to `on_delete=CASCADE`. Deleting a customer therefore deleted their orders, and because `Invoice.order` cascades too, their invoices with them. The admin's confirmation page even listed them, but the deletion was allowed.\n\nOrder history is a financial record: the relation must be `PROTECT` (deleting a customer with orders is refused; use the account-closure flow that anonymises instead), and the change needs a migration so the model state and the migrations agree.\n"}}$mf6be615be$::jsonb, 'lab-bundles/9c4b3daa15ffb5f92c0ee874f19817e1a71d4e3b031feb15f273de41ecca45d8.tar.gz', '9c4b3daa15ffb5f92c0ee874f19817e1a71d4e3b031feb15f273de41ecca45d8', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- dj.data.float-money-rounding@1.0.0
INSERT INTO public.lab_blocks (id, org_id, block_key, kind, stack)
VALUES ('78c3c5b2-1bfc-511a-9669-cb18b8b46fd5', NULL, 'dj.data.float-money-rounding', 'fault', 'django')
ON CONFLICT (org_id, block_key) DO NOTHING;
DO $mfaf6ced50$ BEGIN
  IF EXISTS (SELECT 1 FROM public.lab_blocks WHERE id = '78c3c5b2-1bfc-511a-9669-cb18b8b46fd5' AND (kind <> 'fault' OR stack <> 'django')) THEN
    RAISE EXCEPTION 'lab block % changed kind or stack; block identity is immutable', 'dj.data.float-money-rounding';
  END IF;
  IF EXISTS (SELECT 1 FROM public.lab_block_versions WHERE block_id = '78c3c5b2-1bfc-511a-9669-cb18b8b46fd5' AND version = '1.0.0' AND content_hash <> 'af6ced50aae2f15de1d78cc6342699fcaaabb89a6b4448a4130758ec14f35bfa') THEN
    RAISE EXCEPTION 'lab block % version % is already published with different content; bump the version', 'dj.data.float-money-rounding', '1.0.0';
