END $mfb4baa0dd$;
INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('08ef39fa-ec16-5f50-bd05-b127de59a461', 'a13288fb-e55d-5d7a-b555-c58fc69d98cf', '1.0.0', 'b4baa0dddec3ae97583b4527cb27ee5825cffa06049dec823ee2afbbf8d82ce3', $mfb4baa0dd${"kind":"fault","id":"dj.mig.conflicting-leaf-nodes","version":"1.0.0","stack":"django","title":"Deploy fails: conflicting migrations detected","summary":"Two branches each added an orders migration numbered 0004 on top of 0003, so the migration graph has two leaf nodes and migrate refuses to run.","category":"migrations","difficulty":"beginner","skills":["django-migrations","migration-graph","deployment"],"requires":["slot:migrations.orders","cap:postgres"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"files":[{"path":"orders/migrations/0004_backfill_shipping_names.py","from":"inject/0004_backfill_shipping_names.py"},{"path":"orders/migrations/0004_normalize_currency_codes.py","from":"inject/0004_normalize_currency_codes.py"}]},"fix":{"slots":[{"slot":"migrations.orders","file":"fix/merge_order_branches.py"}],"files":[{"path":"tests/test_migration_graph.py","from":"fix/tests/test_migration_graph.py"}]},"cheats":[{"name":"merge-only-one-branch","slots":[{"slot":"migrations.orders","file":"cheats/partial_merge.py"}]},{"name":"revert-the-commit","slots":[{"slot":"migrations.orders","file":"fix/merge_order_branches.py"}],"files":[{"path":"orders/migrations/0004_normalize_currency_codes.py","from":"cheats/linear_currency_codes.py"},{"path":"ext/stock_alerts/urls.py","from":"cheats/empty_urls.py"}]}],"carrier":{"feature":"stock-alerts","files":[{"path":"ext/stock_alerts/__init__.py","from":"carrier/ext/stock_alerts/__init__.py"},{"path":"ext/stock_alerts/apps.py","from":"carrier/ext/stock_alerts/apps.py"},{"path":"ext/stock_alerts/urls.py","from":"carrier/ext/stock_alerts/urls.py"},{"path":"ext/stock_alerts/views.py","from":"carrier/ext/stock_alerts/views.py"}]},"commit":{"message":"inventory: add a staff endpoint listing products under the low-stock threshold","persona":"Marcus Webb \u003cmarcus@shop.example.com\u003e"},"checks":[{"ref":"check.migrate-from-snapshot","role":"symptom","params":{"steps":[{"cmd":". scripts/dev-env.sh \u0026\u0026 python3 manage.py migrate --noinput","db":"clean","expect_rc":0},{"cmd":". scripts/dev-env.sh \u0026\u0026 python3 manage.py makemigrations --check --dry-run","db":"clean","expect_rc":0}]}}],"symptom":{"vars":{"impact":"Nothing can be deployed until this is fixed: the migration step runs before every release, and staging is already blocked.","observations":"### Other observations from the reporter\n\n- Both migrations are only data fixes; neither changes the schema.\n- The stock alerts endpoint shipped in the same release, so it was suspected first.\n- Running the tests still passes, because the test database is built without migrations.","output":"CommandError: Conflicting migrations detected; multiple leaf nodes in the migration graph: (0004_backfill_shipping_names, 0004_normalize_currency_codes in orders).\nTo fix them run 'python manage.py makemigrations --merge'","report":"The release pipeline failed at the migration step. Two developers each merged a data migration for the orders app the same day. Each of them ran the migrations locally and everything worked on their branch, but the merged main branch cannot be deployed.","support_tried":"Re-ran the pipeline twice (same failure). Considered deleting one of the two new migration files, but both have already been applied on someone's local database and one of them is needed for the finance backfill.","title":"Release blocked: migrate fails with conflicting migrations"},"signature":"Conflicting migrations detected; multiple leaf nodes in the migration graph"},"hints":["Read the error message literally and then look at the orders migrations directory: which migrations exist, and what does each one list in its dependencies? Try python manage.py showmigrations orders and draw the graph.","Django expects the migrations of an app to form a single chain. Two migrations that depend on the same parent are two leaf nodes, and migrate refuses to pick an order. You either make one depend on the other or add a merge migration that depends on both leaves.","Add a merge migration for orders (python manage.py makemigrations --merge, or write it by hand) that depends on both 0004 migrations, commit it, and add a test that asserts the migration graph has no conflicts. Do not delete migrations that may already have been applied somewhere."],"rubric":{"key_points":["Explains the migration graph: nodes, dependencies and why two leaf nodes in one app are a conflict.","Fixes it with a merge migration (or by chaining one migration after the other) instead of deleting applied migrations.","Notes that both migrations may already be applied elsewhere, so history must be preserved.","Adds a check (migration graph test or makemigrations --check in CI) so the conflict is caught before deploy."],"misconceptions":["Deleting one of the migrations or editing the applied ones is the safe fix.","Running the test suite would have caught it (the tests build the database without migrations).","The number in the filename decides the order of migrations (only dependencies do)."]},"root_cause":"Both new orders migrations were numbered `0004` and both declared `0003_orderitem_line_total_required` as their only dependency. That gives the orders app two leaf nodes, and `migrate` (and `makemigrations --check`) stop with `Conflicting migrations detected`. The file numbers are only a naming convention: the dependencies define the graph.\n\nThe fix is a merge migration that depends on both leaves, so the history is preserved and the graph has a single head again; a graph test keeps it from regressing.\n"}}$mfb4baa0dd$::jsonb, 'lab-bundles/34d0f35167f5c7644f909f6ecfc14af6b67d0e6a03b93a29285d66a2cc6e3034.tar.gz', '34d0f35167f5c7644f909f6ecfc14af6b67d0e6a03b93a29285d66a2cc6e3034', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

-- dj.perf.dashboard-repeated-queries@1.0.0
