INSERT INTO public.lab_block_versions (id, block_id, version, content_hash, manifest, payload_key, payload_sha256, changelog)
VALUES ('31c50908-4cea-55db-a30a-7bfc68e0e5df', '1025dc56-e3af-5b63-bbc6-e73690c302f0', '1.0.0', '2cd61d732f5e9b62f959dfee455b0d70a730f350cb53552a84bdd7b8ac2c1a0b', $mf2cd61d73${"kind":"fault","id":"dj.svc.payments-no-timeout","version":"1.0.0","stack":"django","title":"Checkout hangs for half a minute when the payments provider is slow","summary":"The payments client calls the provider without a timeout, so a slow provider ties up checkout requests until the provider answers.","category":"service-comm","difficulty":"beginner","skills":["timeouts","failure-modes","requests"],"requires":["slot:payments.client.request","svc:payments-stub","env:payments-latency"],"budget":{"setup_seconds":0,"workspace_bytes":0,"grader_bytes":0},"fault":{"inject":{"slots":[{"slot":"payments.client.request","value":"response = self.session.post(\n    url,\n    json=payload,\n    headers={\"Idempotency-Key\": str(idempotency_key)},\n)\n"}]},"fix":{"slots":[{"slot":"payments.client.request","value":"response = self.session.post(\n    url,\n    json=payload,\n    headers={\"Idempotency-Key\": str(idempotency_key)},\n    timeout=settings.PAYMENTS_TIMEOUT,\n)\n"}],"files":[{"path":"tests/test_payments_timeout.py","from":"fix/tests/test_payments_timeout.py"}]},"cheats":[{"name":"timeout-none","slots":[{"slot":"payments.client.request","value":"response = self.session.post(\n    url,\n    json=payload,\n    headers={\"Idempotency-Key\": str(idempotency_key)},\n    timeout=None,\n)\n"}]},{"name":"one-hour-timeout","slots":[{"slot":"payments.client.request","value":"response = self.session.post(\n    url,\n    json=payload,\n    headers={\"Idempotency-Key\": str(idempotency_key)},\n    timeout=3600,\n)\n"}]},{"name":"revert-the-commit","slots":[{"slot":"payments.client.request","value":"response = self.session.post(\n    url,\n    json=payload,\n    headers={\"Idempotency-Key\": str(idempotency_key)},\n    timeout=settings.PAYMENTS_TIMEOUT,\n)\n"}],"files":[{"path":"ext/product_feed/urls.py","from":"cheats/empty_urls.py"}]}],"carrier":{"feature":"product-feed","files":[{"path":"ext/product_feed/__init__.py","from":"carrier/ext/product_feed/__init__.py"},{"path":"ext/product_feed/apps.py","from":"carrier/ext/product_feed/apps.py"},{"path":"ext/product_feed/urls.py","from":"carrier/ext/product_feed/urls.py"},{"path":"ext/product_feed/views.py","from":"carrier/ext/product_feed/views.py"}]},"commit":{"message":"catalog: publish a partner product feed","persona":"Sam Okafor \u003csam@shop.example.com\u003e"},"checks":[{"ref":"check.http-behavior","role":"symptom","params":{"steps":[{"body":{"items":[{"product":1,"quantity":1}],"shipping_name":"SVC1-slow-provider"},"expect_status":[502,503,504],"headers":{"Authorization":"Token mf_tok_alice"},"method":"POST","path":"/api/orders/","timeout":25}]}},{"ref":"check.pytest-node","role":"symptom","params":{"paths":["tests/dj_svc_1/test_payments_timeout.py"]}}],"symptom":{"vars":{"expected":"If the provider does not answer promptly, checkout should give up within a few seconds and tell the customer the payment is temporarily unavailable, so requests never pile up.","observations":"### Other observations from the reporter\n\n- Product pages were slow too, although they do not talk to the provider.\n- The partner product feed shipped the same day.\n- The provider was eventually fine again and nothing needed to be repaired afterwards.","report":"This afternoon the payments provider had a slow period. During it, customers who pressed Pay watched the button spin for half a minute or more, many gave up and reloaded (creating more waiting requests), and after a while the whole site felt sluggish even for people who were only browsing.","support_tried":"The provider status page showed slow responses for about 40 minutes. We restarted the web workers, which helped for a minute and then the site slowed down again.","title":"Checkout spins for 30 seconds and then fails during payment provider trouble","where":"Checkout: the step that charges the customer's card through the payments provider."},"signature":"requests to the payments provider wait for the provider with no timeout"},"hints":["Reproduce the provider being slow: the lab has a payments stub that can be made slow with its fault API or environment (see the stub service). Place an order and watch how long the request runs and what the worker is doing while it waits.","A network call without a timeout waits as long as the other side takes: the requests library has no default timeout at all. While it waits, the worker thread and its database transaction are held. Every outbound call needs a timeout (connect and read) and a clear failure mode when it expires.","In payments/client.py the post call has no timeout argument, although the settings define PAYMENTS_TIMEOUT. Pass a sensible (connect, read) timeout, make sure the expiry becomes the service-unavailable answer, and add a test asserting that every request carries a timeout."],"rubric":{"key_points":["Identifies the missing timeout on the outbound HTTP call and explains that requests waits forever by default.","Explains the knock-on effects: held worker threads and open transactions, request pile-up, and unrelated pages slowing down.","Fixes it with explicit connect and read timeouts and a graceful failure (retry policy and a service-unavailable response).","Adds a test asserting that the call carries a finite timeout."],"misconceptions":["Adding more workers or bigger instances solves a slow dependency.","A very large timeout (or timeout=None) is the same as having one.","Retrying without a timeout makes the request more reliable."]},"root_cause":"`PaymentsClient._post` called `session.post(...)` without a `timeout`. The `requests` library never times out by default, so when the provider was slow every checkout request waited for the provider while holding a web worker and an open database transaction. Waiting requests piled up and starved the rest of the site.\n\nThe fix passes the configured `(connect, read)` timeout so a slow provider turns into a fast, explicit `503`.\n"}}$mf2cd61d73$::jsonb, 'lab-bundles/fd55fae88e68d01603223d28fecc6f4507fe697a2aa2e0f68076639314be3346.tar.gz', 'fd55fae88e68d01603223d28fecc6f4507fe697a2aa2e0f68076639314be3346', NULL)
ON CONFLICT (block_id, version) DO NOTHING;

